SELECT COUNT(1)
FROM gb_distributer_pay_list


        AND gb_ndpl_gb_dis_id = #{disId}


        AND gb_ndpl_pay_date = #{date}


        AND gb_ndpl_type = #{type}

SELECT IFNULL(SUM(CAST(gb_ndpl_pay_subtotal AS UNSIGNED)), 0)
FROM gb_distributer_pay_list


        AND gb_ndpl_gb_dis_id = #{disId}


        AND gb_ndpl_pay_date = #{date}


        AND gb_ndpl_type = #{type}

SELECT *
FROM gb_distributer_pay_list


        AND gb_ndpl_gb_dis_id = #{disId}


        AND gb_ndpl_type = #{type}


ORDER BY gb_distributer_pay_list_id DESC

    LIMIT #{offset}, #{limit}
